```javascript
POST /back-office/managed/funds
{
  "userID": "{{ria-user-id}}",
  "name": "Tech Fund",
  "clientFundID": "{{$timestamp}}",
  "description": "A collection of tech stocks, to be used in portfolios",
  "holdings": [
      {
          "instrumentID":"{{inst-AAPL}}",
          "target":0.3
      },
      {
          "instrumentID":"{{inst-AMZN}}",
          "target":0.25
      },
      {
          "instrumentID":"{{inst-TSLA}}",
          "target":0.1
      },
      {
          "instrumentID":"{{inst-MSFT}}",
          "target":0.35
      }
  ],
  "triggers": [
      {
        "type": "TOTAL_DRIFT",
        "maxAllowed": 0.05
      },
      {
        "type": "RELATIVE_DRIFT",
        "child": null,
        "lowerBound": 0.02,
        "upperBound": null
      },
      {
        "type": "ABSOLUTE_DRIFT",
        "child": null,
        "lowerBound": 0.01,
        "upperBound": 0.01
      }
    ]
}
```

